const COMMANDS: &[&str] = &["availability", "respond"];

fn main() {
    // Generates permissions/autogenerated and, when building for iOS, compiles
    // and links the Swift package in ios/ (which pulls in core/).
    tauri_plugin::Builder::new(COMMANDS).ios_path("ios").build();

    // Desktop Tauri has no Swift plugin host, so on macOS the bridge in macos/
    // is compiled and linked here instead. 15.0 matches
    // bundle.macOS.minimumSystemVersion in tauri.conf.json; Foundation Models
    // itself is checked for at run time (and weak-linked by the app's build.rs).
    #[cfg(target_os = "macos")]
    if std::env::var("CARGO_CFG_TARGET_OS").as_deref() == Ok("macos") {
        // As tauri-utils' link_swift_library does: a stray SDKROOT (the iOS one,
        // under `tauri ios`) would point swift build at the wrong SDK.
        let sdk_root = std::env::var_os("SDKROOT");
        std::env::remove_var("SDKROOT");
        swift_rs::SwiftLinker::new("15.0")
            .with_package("AppleAIMac", "macos")
            .link();
        if let Some(root) = sdk_root {
            std::env::set_var("SDKROOT", root);
        }
        println!("cargo:rerun-if-changed=core/Sources");
        println!("cargo:rerun-if-changed=macos/Sources");
    }
}
